using System.IO;
using UnityEditor;
using UnityEngine;

namespace Neram.EditorTools
{
    /// <summary>
    /// First-open helper, once per editor session (never in batch mode, never without confirmation):
    ///  - the generated scene Assets/Scenes/NERAM_OR_Replay.unity does not exist yet -> offer NERAM > 1. Run full setup;
    ///  - the scene exists but was generated by an OLDER setup (no or different NeramSceneStamp version) -> offer to rebuild
    ///    it. An outdated scene is exactly what produces "UIDocument had no PanelSettings" / missing-element errors when
    ///    newer scripts run against it.
    /// </summary>
    [InitializeOnLoad]
    public static class NeramFirstRun
    {
        private const string AskedKey = "NERAM.FirstRun.Asked";

        static NeramFirstRun()
        {
            if (Application.isBatchMode) return;
            EditorApplication.delayCall += Ask;
        }

        private static void Ask()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling || EditorApplication.isUpdating)
            {
                EditorApplication.delayCall += Ask; // try again once the Editor is idle
                return;
            }
            if (SessionState.GetBool(AskedKey, false)) return;
            SessionState.SetBool(AskedKey, true);
            var scene = Path.Combine(Path.GetDirectoryName(Application.dataPath) ?? "", NeramSetup.ScenePath);
            if (File.Exists(scene))
            {
                var text = File.ReadAllText(scene);
                if (text.Contains("generatorVersion: " + Neram.Unity.NeramVersion.Value)) return;
                if (EditorUtility.DisplayDialog("NERAM scene is outdated",
                        "Assets/Scenes/NERAM_OR_Replay.unity was generated by an older NERAM setup (scene stamp is not v" + Neram.Unity.NeramVersion.Value + ").\n\n" +
                        "Running the new scripts against it can leave the dashboard without PanelSettings/UXML. Rebuild the scene now with NERAM > 1. Run full setup?",
                        "Rebuild now", "Later"))
                    NeramSetup.RunFullSetupMenu();
                return;
            }
            if (EditorUtility.DisplayDialog("NERAM first run",
                    "The NERAM theatre scene has not been generated in this project yet.\n\n" +
                    "Run NERAM > 1. Run full setup now? It syncs the replays from the workspace, builds the scene and validates the project " +
                    "(about a minute).", "Run setup now", "Later"))
                NeramSetup.RunFullSetupMenu();
        }
    }
}
